begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not p.prosecdef and p.proconfig @> array['search_path=""'],'scan uses invoker rights and fixed path') from pg_proc p where p.oid='public.scan_mobile_push_maintenance(text,integer,timestamptz)'::regprocedure;
select ok(not has_function_privilege('anon','public.scan_mobile_push_maintenance(text,integer,timestamptz)','execute'),'anonymous cannot scan');
select ok(not has_function_privilege('authenticated','public.scan_mobile_push_maintenance(text,integer,timestamptz)','execute'),'authenticated cannot scan');
select ok(has_function_privilege('service_role','public.scan_mobile_push_maintenance(text,integer,timestamptz)','execute'),'service can scan');
select ok(relrowsecurity,'scan state has RLS') from pg_class where oid='public.mobile_push_maintenance_scans'::regclass;
select ok(not has_table_privilege('authenticated','public.mobile_push_maintenance_scans','select'),'users cannot read scan state');
select ok(not has_table_privilege('anon','public.mobile_push_maintenance_scans','update'),'anonymous cannot change scan state');
select ok(not has_table_privilege('service_role','public.mobile_push_maintenance_scans','delete'),'service cannot erase scan state');
insert into auth.users(id,email,aud,role,created_at) values('a9700000-0000-4000-8000-000000000001','push-scan@example.invalid','authenticated','authenticated',now());
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('a9700000-0000-4000-8000-000000000002','a9700000-0000-4000-8000-000000000001','post_saved','social','Fixture','Local only');
insert into public.mobile_push_deliveries(id,notification_id,user_id,expo_push_token,platform,send_status,receipt_status,attempt_count,created_at,retry_claim_id,retry_outcome)
select ('a9700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'a9700000-0000-4000-8000-000000000002','a9700000-0000-4000-8000-000000000001','ExponentPushToken[scan]','ios','error','error',3,'2026-01-01',gen_random_uuid(),'{"status":"sent","ticket_id":"fixture","attempt_count":1}'::jsonb from generate_series(3,5) n;
set local role service_role;
select throws_ok($$select public.scan_mobile_push_maintenance('bad',1,now())$$,'22023',null,'reject invalid phase');
select throws_ok($$select public.scan_mobile_push_maintenance('recorded',101,now())$$,'22023',null,'recovery capped at 100');
select throws_ok($$select public.scan_mobile_push_maintenance('receipts',1001,now())$$,'22023',null,'receipts capped at 1000');
select throws_ok($$select public.scan_mobile_push_maintenance('retries',0,now())$$,'22023',null,'reject zero batch');
select throws_ok($$select public.scan_mobile_push_maintenance(null,1,now())$$,'22023',null,'reject null phase');
select throws_ok($$select public.scan_mobile_push_maintenance('recorded',1,null)$$,'22023',null,'reject null clock');
select is(public.scan_mobile_push_maintenance('recorded',1,now())->0->>'id','a9700000-0000-4000-8000-000000000003','first tied timestamp uses ID order');
select is(public.scan_mobile_push_maintenance('recorded',1,now())->0->>'id','a9700000-0000-4000-8000-000000000004','next pass progresses without changing failed rows');
insert into public.mobile_push_deliveries(id,notification_id,user_id,expo_push_token,platform,send_status,receipt_status,attempt_count,created_at,retry_outcome)
select 'a9700000-0000-4000-8000-000000000006',notification_id,user_id,expo_push_token,platform,send_status,receipt_status,attempt_count,'2026-01-02',retry_outcome from public.mobile_push_deliveries where id='a9700000-0000-4000-8000-000000000003';
select is(public.scan_mobile_push_maintenance('recorded',100,now())->0->>'id','a9700000-0000-4000-8000-000000000005','sweep stops at saved upper bound');
select is(public.scan_mobile_push_maintenance('recorded',1,now())->0->>'id','a9700000-0000-4000-8000-000000000003','new arrivals do not postpone revisit');
select is(jsonb_array_length(public.scan_mobile_push_maintenance('recorded',100,now())),3,'new sweep includes arrival');
select is(public.scan_mobile_push_maintenance('retries',100,now()),'[]'::jsonb,'saved outcomes and exhausted budget excluded from sends');
update public.mobile_push_deliveries set retry_outcome=null,attempt_count=1 where id='a9700000-0000-4000-8000-000000000003';
select is(public.scan_mobile_push_maintenance('retries',100,now())->0->>'id','a9700000-0000-4000-8000-000000000003','eligible retry independently scanned');
update public.mobile_push_deliveries set send_status='sent',receipt_status='pending',sent_at=now()-interval '14 minutes' where id='a9700000-0000-4000-8000-000000000003';
select is(public.scan_mobile_push_maintenance('receipts',100,now()),'[]'::jsonb,'young receipt excluded');
select is(public.scan_mobile_push_maintenance('receipts',100,now()+interval '1 minute')->0->>'id','a9700000-0000-4000-8000-000000000003','receipt admitted at fifteen minutes');
reset role;
select * from finish();
rollback;
